export default function NavItem({ icon, label, active, onClick, badge, id }) {
  const [isHovered, setIsHovered] = useState(false);

  // 2. Define the glow color (matches your Agro Zenith green)
  const glowColor = "rgba(52, 211, 153, 0.4)";
  return (
    <button
      onClick={() => onClick(id)}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      style={{
        display:       "flex",
        alignItems:    "center",
        gap:           10,
        padding:       "9px 12px",
        borderRadius:  8,
        cursor:        "pointer",
        width:         "100%",
        textAlign:     "left",
        background:    active ? "rgba(255,255,255,0.13)" : "transparent",
        color:         active ? "#fff" : "rgba(255,255,255,0.6)",
        /* Use box-shadow instead of border — border causes 1px layout shift */
        border:        "none",
        boxShadow:     active ? "inset 0 0 0 1px rgba(255,255,255,0.18)" : "none",
        fontSize:      13.5,
        fontWeight:    active ? 500 : 400,
        transition:    "background 0.14s, color 0.14s",
        position:      "relative",
        userSelect:    "none",
      }}
    >
      <span style={{ fontSize: 16, width: 22, textAlign: "center", flexShrink: 0 }}>
        {icon}
      </span>
      <span style={{ flex: 1 }}>{label}</span>
      {badge && (
        <span style={{
          background:   "#b83232",
          color:        "#fff",
          borderRadius: 10,
          fontSize:     10,
          padding:      "1px 5px",
          minWidth:     16,
          textAlign:    "center",
          flexShrink:   0,
        }}>
          {badge}
        </span>
      )}
    </button>
  );
}
